const same = (a, b) => JSON.stringify(a) === JSON.stringify(b)
const SAVED = [['edits.json', editsFile], ['build.sh', buildFile], ['patch.py', patchFile], ['multiselect.py', path.join(mod, 'multiselect.py')]]
console.log('JR folder: ' + root)

const E = JSON.parse(fs.readFileSync(editsFile, 'utf8'))
const now = E.files[PICKER]
if (same(now, NEW_PICKER) && same(E.files[SHOP], NEW_SHOP)) {
  console.log('  Already installed (' + E.id + '). Nothing changed.')
  process.exit(0)
}
const v1 = EARLIER.some(([p, sh]) => same(now, p) && same(E.files[SHOP], sh))
if (!v1 && (!same(now, OLD_PICKER) || E.files[SHOP])) {
  throw new Error('edits.json is not the trade multi-select version this update was made for. Nothing was changed.')
}
for (const f of [buildFile, patchFile]) if (!fs.existsSync(f)) throw new Error(`${path.relative(root, f)} is missing. Nothing was changed.`)
if (v1) console.log('  Updating an earlier version of the shop update')
// 1. backup (only of the files from before the shop update)
if (!fs.existsSync(backup) && !v1) {
  fs.mkdirSync(backup)
  for (const [name, file] of SAVED) if (fs.existsSync(file)) fs.copyFileSync(file, path.join(backup, name))
  console.log('  Saved the old files in tools\\game-mod\\shop-update\\backup')
}
// 2. edits.json
const old = E.id
E.files[PICKER] = NEW_PICKER
E.files[SHOP] = NEW_SHOP
E.files = Object.fromEntries(Object.entries(E.files).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)))
if (!E.classes.includes(CLASS)) E.classes.push(CLASS)
const { id, ...body } = E
const ordered = { ffdec: body.ffdec, classes: body.classes, files: body.files }
const newId = crypto.createHash('sha1').update(JSON.stringify(ordered, null, 1)).digest('hex').slice(0, 10)
fs.writeFileSync(editsFile, JSON.stringify({ ...ordered, id: newId }, null, 1) + '\n')
console.log(`  edits.json updated (${old} -> ${newId})`)
// 3. build.sh: the class list must match edits.json
const sh = fs.readFileSync(buildFile, 'utf8')
const m = /^classes=(.*)$/m.exec(sh)
if (m && !m[1].split(',').includes(CLASS)) fs.writeFileSync(buildFile, sh.replace(/^classes=(.*)$/m, (l) => l.trimEnd() + ',' + CLASS))
console.log('  build.sh: shop.ShopToSell in the class list')
// 4. patch.py runs shop.py
const line = "exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'shop.py'), encoding='utf-8').read())\n"
let py = fs.readFileSync(patchFile, 'utf8')
if (!py.includes(line)) {
  const at = py.lastIndexOf("print('ok')")
  py = at >= 0 ? py.slice(0, at) + line + py.slice(at) : py + (py.endsWith('\n') ? '' : '\n') + line
  fs.writeFileSync(patchFile, py)
}
console.log('  patch.py runs shop.py')
// 5. the new source files
fs.copyFileSync(path.join(here, 'multiselect.py'), path.join(mod, 'multiselect.py'))
fs.copyFileSync(path.join(here, 'shop.py'), path.join(mod, 'shop.py'))
console.log('  multiselect.py and shop.py copied in')
console.log('Done. Start JR, press Play, log in, and leave JR open until the log says the in-game features are ready.')
